// All script elements for Hollywood Animal, derived from the game's config files.
// Unlock conditions use the game's raw format and are parsed at runtime.

export interface ScriptElement {
  id: string;
  label: string;
  art: number;
  com: number;
  unlock: string;
}

export interface ScoreResult {
  art: number;
  com: number;
  synergy: number;
  pollux: number;
}

