export const GENRE_PAIR_MODIFIERS: Record<string, { art: number; com: number }> = {};
for (const [a, b, art, com] of RAW_GENRE_PAIRS) {
  GENRE_PAIR_MODIFIERS[`${a}|${b}`] = { art, com };
  GENRE_PAIR_MODIFIERS[`${b}|${a}`] = { art, com };
}

